    val category: String,
    val layer: String,
    val overview: String,
    val technical: String,
    val usage: String,
    val function: String,
    val pros: String,
    val cons: String,
    val hurdles: String,
    val standard: String,
    val fit: String,
    val environment: String
)

private fun protocol(
